// worley3x F2 - F1: zero on a cell border -- the creases of grained leather, rougher and darker.
// The hide is the base colour and roughness; cell is a grain's size in mm.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let w = worley3x(q / cell, 5u);
let crease = 1.0 - smoothstep(0.0, creaseWidth, w.y - w.x);
m.baseColor = mix(m.baseColor, creaseColor, crease);
m.roughness = mix(m.roughness, creaseRough, crease);

