relief.code:
// Hammered: a dent "amplitude" mm deep in every cell of a Worley pattern "size" mm across, with
// the ridges between them sharp, as a hammer leaves them. F1 grows at most 1 per cell, so the
// dent's slope is at most 2 amplitude / size.
let w = worley3(q / size, 7u);
let dent = 1.0 - clamp(w.x, 0.0, 1.0);
h = -amplitude * dent * dent;
slope = 2.0 * amplitude / size;

material.code:
// worley3x cell number: each grain its own mineral -- light (the base colour), pink or dark --
// as in granite. grain is a crystal's size in mm; the shares are how many of them are pink and
// dark; edge darkens the boundaries between them.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let w = worley3x(q / grain, 6u);
let c = select(select(m.baseColor, pink, w.z < darkShare + pinkShare), dark, w.z < darkShare);
m.baseColor = c * (1.0 - edge + edge * smoothstep(0.0, 0.1, w.y - w.x));

// Veins about `veinSpacing` mm apart, bent by five octaves of noise over `size` mm -- the stone's
// movement -- by `turbulence` spacings; `sharpness` is how thin a vein is, and `cloud` a soft grey
// between them, as Carrara has.
let q = p_local * S_local / mm(1.0)/size;   // the point in mm, moving with the object
let nz = fbm3(q  , 3u, 5u, 2.0, 0.5);
let v = pow(1.0 - abs(sin(PI * (q.x / veinSpacing + turbulence * nz.w))), sharpness);
let cl = 0.5 + 0.5 * fbm3(q / 0.5 , 4u, 3u, 2.0, 0.5).w;
m.baseColor = mix(mix(m.baseColor, vein, cloud * cl), vein, v);

// worley3x: every cell a chip of stone -- one of three, in shares -- and F2 - F1 below `gap` (in cells)
// the cement between them, the base colour. spacing is a chip's size in mm.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let w = worley3x(q / spacing, 4u);
let stone = select(select(chipC, chipB, w.z < shareA + shareB), chipA, w.z < shareA);
m.baseColor = mix(m.baseColor, stone, smoothstep(gap - softness, gap + softness, w.y - w.x));

// Three octaves of gradient noise `size` mm across: the base colour and roughness where it is low,
// the second ones where it is high.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let t = smoothstep(0.0, 1.0, 0.5 + 0.6 * fbm3(q / size, 1u, 3u, 2.0, 0.5).w);
m.baseColor = mix(m.baseColor, second, t);
m.roughness = mix(m.roughness, secondRough, t);

// gnoise3 bending layers laid down along the object's z: a layer every `layer` mm, bent by
// `warp` layers by noise `size` mm across -- and a grit of sand grains `grit` mm across.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let g = gnoise3(q / size, 2u).w;
let b = 0.5 + 0.5 * sin(2.0 * PI * (q.z / layer + warp * g));
let sand = 1.0 - gritAmount + 2.0 * gritAmount * (0.5 + 0.5 * vnoise3(q / grit, 9u).w);
m.baseColor = mix(m.baseColor, band, b * b) * sand;

// Rings about an axis along the object's z -- the heart of the log, `heart` mm along x from the
// object's origin, so a board cut beside it shows arcs on its face and stripes on its edges --
// one every `ring` mm: the base colour (earlywood) darkening into latewood over the last
// `lateShare` of each, then starting again, as a year does. Gradient noise `wobbleSize` mm across
// (longer along z) bends them by `wobble` rings; fibres `fibre` mm wide and twenty times as long
// run along z.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let bend = gnoise3(q / vec3<f32>(wobbleSize, wobbleSize, 4.0 * wobbleSize), 7u).w;
let r = fract(length(q.xy - vec2<f32>(heart, 0.0)) / ring + wobble * bend);
let late = smoothstep(1.0 - lateShare, 1.0, r);
let fib = 0.5 + 0.5 * vnoise3(q / vec3<f32>(fibre, fibre, 20.0 * fibre), 8u).w;
m.baseColor = mix(m.baseColor, latewood, late) * (1.0 - fibreAmount + 2.0 * fibreAmount * fib);
m.roughness = min(1.0, m.roughness + 0.15 * late);

// worley3x: each granule (`granule` mm) lighter or darker by up to `mottle`, and the gaps between
// them (F2 - F1 near zero) the pore colour.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let w = worley3x(q / granule, 3u);
let shade = 1.0 - mottle + 2.0 * mottle * w.z;
let pore = 1.0 - smoothstep(0.0, poreWidth, w.y - w.x);
m.baseColor = mix(m.baseColor * shade, poreColor, pore);

// Stains: four octaves of noise `stainSize` mm across. Pores: in a `poreShare` of the Worley cells
// `poreSpacing` mm apart, a hole `poreRadius` of a cell across -- darker, and rough.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let st = 0.5 + 0.5 * fbm3(q / stainSize, 11u, 4u, 2.0, 0.5).w;
let w = worley3x(q / poreSpacing, 12u);
let pore = (1.0 - smoothstep(0.6 * poreRadius, poreRadius, w.x)) * step(1.0 - poreShare, w.z);
m.baseColor = mix(m.baseColor, stain, stainAmount * smoothstep(0.35, 0.75, st)) * (1.0 - 0.7 * pore);
m.roughness = mix(m.roughness, 1.0, pore);

// Five octaves of noise `patchSize` mm across: where it is in the top `coverage`, rust -- its
// shade varying on a fifth of that -- not a metal any more, rough and with a plain coat.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let f = 0.5 + 0.5 * fbm3(q / patchSize, 21u, 5u, 2.0, 0.5).w;
let r = smoothstep(1.0 - coverage - softness, 1.0 - coverage + softness, f);
let tone = 0.5 + 0.5 * vnoise3(q / (0.2 * patchSize), 22u).w;
m.baseColor = mix(m.baseColor, mix(rust, rustLight, tone), r);
m.metallic = m.metallic * (1.0 - r);
m.roughness = mix(m.roughness, rustRough, r);
m.specular = mix(m.specular, 0.5, r);

// worley3x -- two Worley lattices crossed, so the spangles keep to no grid: a spangle every `spangle`
// mm, each with its own grain direction in the object's xy (the anisotropy), and a roughness and
// brightness up to `spread` either side of the base ones.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let w = worley3x(q / spangle, 31u);
let a = 2.0 * PI * w.z;
m.tangent = grainAlong(R_local, vec3<f32>(cos(a), sin(a), 0.0));
m.roughness = m.roughness * (1.0 - spread + 2.0 * spread * fract(w.z * 13.0));
m.baseColor = m.baseColor * (1.0 - 0.5 * spread + spread * fract(w.z * 29.0));

// The base colour and the second in alternate cubes `square` mm on a side, moving with the object -- drawn as a
// wave, so the edges can be softened and the squares shrunk to dots. s is +1 or -1 at a cube's centre and 0 where
// two cubes meet; the second colour is where s is above `level`, blended over `softness` either side of it:
//   level 0            the checker: softness 0 sharp edges, 1 as soft as the wave itself
//   level up to 1      round dots of the second colour, shrinking, in alternate squares: on a face through cube
//                      centres, a dot of radius r mm at level = cos(PI * r / square)
//   level down to -1   the reverse: dots of the base colour in the other squares
// A cube's centre is at the object's origin (cos, not sin), so the floor's plane z = 0, and a box whose half-sizes
// are whole squares, have faces through centres. A flat face half a square off that -- where two cubes meet -- has
// s = 0 all over and shows no squares: change `square` for that object.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let w = cos(PI * q / square);
let s = w.x * w.y * w.z;
let e = max(softness, 1e-4);           // smoothstep's two edges must differ
m.baseColor = mix(m.baseColor, second, smoothstep(level - e, level + e, s));

// A 2x2 twill: tows `tow` mm wide along the object's x and y, over two and under two, stepping one
// per row -- the diagonal a twill has. Each tow is brushed along its fibres (the anisotropy), so
// the weave shows as the light moves; darker by `dip` at its edges, where it goes under.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let c = floor(q.xy / tow);
let alongX = ((i32(c.x) + i32(c.y)) & 3) < 2;
m.tangent = select(grainAlong(R_local, VEC3(0.0, 1.0, 0.0)), grainAlong(R_local, VEC3(1.0, 0.0, 0.0)), alongX);
let f = fract(q.xy / tow);
let across = select(f.x, f.y, alongX);
m.baseColor = m.baseColor * (1.0 - dip + dip * sin(PI * across));
